def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            continue
        grid[x-1][y-1] = val

    # Initialize the DP table
    dp = [[[-float('inf')] * 2 for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp[i][j][0] = max(dp[i][j][0], dp[i-1][j][0] + grid[i][j])
            if j > 0:
                dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][1] + grid[i][j])

    # Find the maximum sum of values collected on the two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            max_sum = max(max_sum, dp[i][j][0] + dp[i][j][1] - grid[i][j])

    return max_sum

