        return "1/1"

    current_sum = 0
    level = 1
    while current_sum + level < N:
        current_sum += level
        level += 1

    difference = N - current_sum
    if level % 2 == 0:
        numerator = difference
        denominator = level - difference + 1
    else:
        numerator = level - difference + 1
        denominator = difference

    return f"{numerator}/{denominator}"

