    # Count the number of chatting pairs that can be separated by adding an aisle in each possible position
    row_effects = [0] * (M + 1)
    col_effects = [0] * (N + 1)

    for a, b, c, d in chatting_pairs:
        if a == c:  # Vertical chatting
            row_effects[a] += 1
            row_effects[c + 1] -= 1
        if b == d:  # Horizontal chatting
            col_effects[b] += 1
            col_effects[d + 1] -= 1

    # Calculate the cumulative effects for rows and columns
    for i in range(1, M + 1):
        row_effects[i] += row_effects[i - 1]

    for j in range(1, N + 1):
        col_effects[j] += col_effects[j - 1]

    # Select the most effective positions for aisles
    top_row_aisles = []
    for i in range(1, M + 1):
