def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a DP array where dp[i][j] represents the maximum importance value that can be achieved with a budget of j using the first i items
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Iterate over each item
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        # Iterate over each possible budget
        for j in range(1, n + 1):
            # If the current item's price is less than or equal to the current budget, consider including it
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
            else:
                # Otherwise, don't include the item
                dp[i][j] = dp[i - 1][j]

    # The maximum importance value that can be achieved with the given budget using all items is stored in dp[m][n]
    return dp[m][n]

