    # Initialize a list to store the maximum importance for each budget from 0 to n
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the dp list in reverse order to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum happiness value is the maximum value in the dp list
    return dp[n]

