    def longest_increasing_subseq(nums):
        dp = [1] * n
        for i in range(1, n):
            for j in range(i):
                if nums[i] > nums[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    max_increasing = longest_increasing_subseq(heights)
    max_decreasing = longest_increasing_subseq(heights[::-1])
    return n - (max_increasing + max_decreasing - 1)

