def min_groups(w, n, prices):
    def can_form_group(max_price):
        count = 0
        i, j = 0, n - 1
        while i <= j:
            if prices[i] + prices[j] <= max_price:
                i += 1
            count += 1
            j -= 1
        return count

    if n == 0:
        return 0
    prices.sort()
    low, high = prices[0], sum(prices)
    while low < high:
        mid = (low + high) // 2
        if can_form_group(mid) <= n:
            high = mid
        else:
            low = mid + 1
    return low

